  'schaal.0a': K('Plattegrond met hokjes', ['Elk hokje is zoveel meter.', 'Aantal hokjes × meter per hokje.'], { model: VTABEL, valkuilen: ['Opgeteld.'], concreter: 'Teken de hokjes.' }),
  'schaal.1a': K('Kaart: 1 cm is … m', ['Elke cm op de kaart is zoveel m in het echt.', 'cm op de kaart × meter per cm.'], { model: VTABEL, valkuilen: ['Opgeteld.'], concreter: 'Tabel 1 cm → 100 m, 2 cm → ?' }),
  'schaal.2a': K('Schaal 1 : 20 000 naar km', ['1 cm op de kaart is 20 000 cm in het echt.', 'cm op de kaart × 20 000.', 'Reken om: cm → m (: 100) → km (: 1000).'], { model: VTABEL + ' + de maten-trap', valkuilen: ['Vergeten om te rekenen naar km.'], concreter: 'Eerst: hoeveel meter is 20 000 cm?' }),
  'schaal.3b': K('Echte afstand naar kaart', ['Reken de echte afstand om naar cm.', 'Deel door het schaalgetal.'], { model: VTABEL, valkuilen: ['Keer in plaats van delen.'], concreter: 'Klein: 1 km op schaal 1 : 100 000.' }),
  'schaal.3c': K('Schaal bepalen', ['Reken de echte afstand om naar cm.', '1 cm op de kaart is … cm echt: deel door de cm op de kaart.'], { model: VTABEL, valkuilen: ['In meters laten staan.'], concreter: 'Tabel: 5 cm → 250 000 cm, 1 cm → ?' }),

  // ================= MATEN =================
  'metriek.0a': K('Maten omrekenen: één stap (km/m, kg/g, m/dm)', ['Hoeveel kleine maten zitten in 1 grote maat? (kilo = 1000, deci = een tiende)', 'Naar een kleinere maat: keer. Naar een grotere maat: delen.'], { model: 'de maten-trap: km – hm – dam – m – dm – cm – mm (elke tree × 10)', woorden: 'Kan Het Dametje Met De Centimeter Meten', valkuilen: ['Verkeerde kant op (keer i.p.v. delen) → "Wordt het getal groter of kleiner? Een kleinere maat → meer van."'], concreter: 'Een meetlat: hoeveel dm is 1 meter?' }),
  'metriek.1a': K('Maten omrekenen: × of : 100/1000', ['Tel op de trap hoeveel treden het is.', 'Elke tree × 10 (naar beneden) of : 10 (naar boven).'], { model: 'de maten-trap', valkuilen: ['Eén tree te veel/weinig.', 'Verkeerde kant op.'], concreter: 'Meetlint/liter-pak erbij.' }),
  'metriek.2a': K('Inhoudsmaten (liter – dl – cl – ml)', ['Trap: liter – dl – cl – ml.', 'Tel de treden; elke tree × 10 of : 10.'], { model: 'de maten-trap voor inhoud', valkuilen: ['Lengte-trap gebruikt.'], concreter: 'Een pak melk van 1 liter.' }),
  'metriek.3a': K('Oppervlakte- en inhoudsmaten (ha, m², m³)', ['Ken de maat: 1 ha = 100 m × 100 m = 10 000 m²; 1 m³ = 1000 dm³ = 1000 liter.', 'Keer het aantal.'], { model: 'een vierkant van 100 bij 100 m; een kubus', valkuilen: ['× 100 i.p.v. × 10 000 → bij m² gaat het per tree × 100.'], concreter: 'Een voetbalveld is ongeveer een hectare.' }),

  // ================= OMTREK, OPPERVLAKTE, INHOUD =================
  'oppervlakte.0a': K('Hokjes tellen (rechthoek)', ['Tel de hokjes in één rij.', 'Tel de rijen.', 'Rijen × hokjes per rij.'], { model: 'het rooster', valkuilen: ['Rand geteld.'], concreter: 'Tel rij voor rij.' }),
  'oppervlakte.0b': K('Omtrek van een rechthoek (klein)', ['Omtrek = de rand rondom.', 'Tel alle zijden op (2 lange + 2 korte).'], { model: 'met de vinger langs de rand', woorden: 'omtrek (de rand rondom)', valkuilen: ['Lengte × breedte (oppervlakte) → "Omtrek is de rand, niet wat erin past."', 'Maar twee zijden opgeteld.'], concreter: 'Loop in gedachten om het boekje.' }),
  'oppervlakte.1a': K('Oppervlakte rechthoek', ['Oppervlakte = hoeveel vierkantjes erin passen.', 'Lengte × breedte.'], { model: 'rooster', woorden: 'oppervlakte, m²', valkuilen: ['Opgeteld (omtrek) → "Hoeveel vierkantjes van 1 m passen erin?"'], concreter: 'Teken een rooster.' }),
